/**
 * Response helpers. Authenticated API responses are always `no-store` so a
 * shared cache or a returning browser never serves another member's data
 * (spec SEC-03, MEDIA-07).
 */
import { AppError, type ErrorCode, type FieldErrors } from '../errors.js'

export const NO_STORE = 'no-store, no-cache, must-revalidate, private'

export interface JsonOptions {
  status?: number
  headers?: HeadersInit
  /** Allow caching; only for responses with no member-specific content. */
  cacheable?: boolean
}

export function json(body: unknown, options: JsonOptions = {}): Response {
  const headers = new Headers(options.headers)
  headers.set('content-type', 'application/json; charset=utf-8')
  if (!options.cacheable) headers.set('cache-control', NO_STORE)
  headers.set('x-content-type-options', 'nosniff')
  return new Response(JSON.stringify(body), { status: options.status ?? 200, headers })
}

export function noContent(headers?: HeadersInit): Response {
  const h = new Headers(headers)
  h.set('cache-control', NO_STORE)
  return new Response(null, { status: 204, headers: h })
}

export function redirect(location: string, status: 302 | 303 | 307 = 303, headers?: HeadersInit): Response {
  const h = new Headers(headers)
  h.set('location', location)
  h.set('cache-control', NO_STORE)
  return new Response(null, { status, headers: h })
}

export interface ErrorBody {
  error: {
    code: ErrorCode
    message: string
    field_errors?: FieldErrors
    detail?: Record<string, unknown>
  }
  request_id: string
}

/**
 * Renders an error. Only AppError detail reaches the client; anything else is
 * reported as a generic internal error with the request id to correlate logs.
 */
export function errorResponse(err: unknown, requestId: string): Response {
  const appError =
    err instanceof AppError
      ? err
      : new AppError('internal', '처리 중 문제가 발생했습니다. 잠시 후 다시 시도해 주세요.', { cause: err })

  const body: ErrorBody = {
    error: { code: appError.code, message: appError.message },
    request_id: requestId,
  }
  if (appError.fieldErrors && Object.keys(appError.fieldErrors).length > 0) {
    body.error.field_errors = appError.fieldErrors
  }
  if (appError.detail) body.error.detail = appError.detail

  const headers = new Headers()
  if (appError.retryAfter !== undefined) {
    headers.set('retry-after', String(Math.max(1, Math.ceil(appError.retryAfter))))
  }
  if (appError.code === 'unauthenticated' || appError.code === 'mfa_required') {
    headers.set('www-authenticate', 'Session realm="insight"')
  }
  return json(body, { status: appError.status, headers })
}

// ------------------------------------------------------------------- SSE --

/** One server-sent event frame. */
export interface SseEvent {
  event?: string
  data: unknown
  id?: string
  retry?: number
}

export function encodeSse(event: SseEvent): string {
  const lines: string[] = []
  if (event.id) lines.push(`id: ${event.id}`)
  if (event.event) lines.push(`event: ${event.event}`)
  if (event.retry !== undefined) lines.push(`retry: ${event.retry}`)
  const payload = typeof event.data === 'string' ? event.data : JSON.stringify(event.data)
  for (const line of payload.split('\n')) lines.push(`data: ${line}`)
  return `${lines.join('\n')}\n\n`
}

/**
 * Wraps an async generator of events as a streaming response. Used for AI
 * token streaming (streaming is the default) and the change-hint channel.
 */
export function sse(
  generator: AsyncGenerator<SseEvent, void, unknown>,
  options: { signal?: AbortSignal } = {},
): Response {
  const encoder = new TextEncoder()
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const send = (event: SseEvent) => controller.enqueue(encoder.encode(encodeSse(event)))
      try {
        // Open the stream immediately so proxies do not buffer the first chunk.
        send({ event: 'open', data: { ok: true } })
        for await (const event of generator) {
          if (options.signal?.aborted) break
          send(event)
        }
      } catch (err) {
        const message = err instanceof AppError ? err.message : '스트리밍이 중단되었습니다.'
        const code = err instanceof AppError ? err.code : 'internal'
        send({ event: 'error', data: { code, message } })
      } finally {
        try {
          send({ event: 'done', data: { ok: true } })
        } catch {
          // controller already closed
        }
        controller.close()
      }
    },
    cancel() {
      void generator.return(undefined)
    },
  })

  return new Response(stream, {
    status: 200,
    headers: {
      'content-type': 'text/event-stream; charset=utf-8',
      'cache-control': NO_STORE,
      connection: 'keep-alive',
      // Tells nginx-style proxies not to buffer the stream.
      'x-accel-buffering': 'no',
    },
  })
}

/** Streams bytes with an explicit content type, never cached. */
export function bytes(
  body: BodyInit,
  contentType: string,
  options: { status?: number; headers?: HeadersInit; filename?: string } = {},
): Response {
  const headers = new Headers(options.headers)
  headers.set('content-type', contentType)
  headers.set('cache-control', NO_STORE)
  headers.set('x-content-type-options', 'nosniff')
  if (options.filename) {
    headers.set('content-disposition', `inline; filename="${encodeURIComponent(options.filename)}"`)
  }
  return new Response(body, { status: options.status ?? 200, headers })
}
