/bin/bash -lc "node --input-type=module <<'NODE'
import { registerHooks, stripTypeScriptTypes } from 'node:module';
import { readFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import assert from 'node:assert/strict';
const target = 'packages/core/src/domain/eligibility.ts';
const baseline = execFileSync('git', ['show', "'`main:${target}`], { encoding: '"'utf8' });
registerHooks({
  resolve(specifier, context, next) {
    try { return next(specifier, context); }
    catch (err) {
      if (specifier.endsWith('.js') && context.parentURL?.startsWith('file:')) {
        const candidate = new URL(specifier.replace(/\\.js"'$/, '"'.ts'), context.parentURL);
        if (existsSync(candidate)) return { url: candidate.href, shortCircuit: true };
      }
      throw err;
    }
  },
  load(url, context, next) {
    if (url.startsWith('file:') && new URL(url).pathname.endsWith('.ts')) {
      const source = url.endsWith('?baseline') ? baseline : readFileSync(fileURLToPath(url), 'utf8');
      return { format: 'module', source: stripTypeScriptTypes(source), shortCircuit: true };
    }
    return next(url, context);
  }
});
const current = await import(pathToFileURL("'`${process.cwd()}/${target}`).href);
const old = await import(pathToFileURL(`${process.cwd()}/${target}`).href + '"'?baseline');
for (const required of [true, false]) {
  for (const length of [500, 501, 700]) {
    const url = 'https://example.com/?q='.padEnd(length, 'a');
    const form = current.parseForm([{ text: '증빙', kind: 'url', required }]);
    const before = old.judgeSubmission(form, { f1: url });
    assert.equal(before.f1.length, 500);
    if (length === 500) assert.equal(current.judgeSubmission(form, { f1: url }).f1, url);
    else assert.throws(() => current.judgeSubmission(form, { f1: url }), (err) =>
      err.code === 'validation_failed' && err.fieldErrors['submission.f1'].includes('500자') && "'!JSON.stringify(err).includes(url));
    console.log(JSON.stringify({ required, length, before: before.f1.length, after: length === 500 ? '"'preserved' : 'validation_failed' }));
  }
}
